// Thresholds (V)
const WARN_THRESHOLD_V = 0.020; // 20 mV
const CRIT_THRESHOLD_V = 0.050; // 50 mV
const MAX_TEMP_WARN = 45.0;
const MAX_TEMP_CRIT = 60.0;

let data = msg.payload;
if (!data || !Array.isArray(data.cell_voltages) || data.cell_voltages.length === 0) {
    msg.status = 'SENSOR_FAULT';
    msg.reason = 'Missing or invalid cell voltages';
    return [null, null, null, msg];
}

let voltages = data.cell_voltages.filter(v => v !== null && !isNaN(v));
if (voltages.length < data.cell_voltages.length || voltages.length === 0) {
    msg.status = 'SENSOR_FAULT';
    msg.reason = 'Incomplete telemetry or NaN cell readings';
    return [null, null, null, msg];
}

let v_max = Math.max(...voltages);
let v_min = Math.min(...voltages);
let delta_v = v_max - v_min;
let delta_v_mv = delta_v * 1000.0;

let temps = (data.cell_temperatures || []).filter(t => t !== null && !isNaN(t));
let t_max = temps.length > 0 ? Math.max(...temps) : 25.0;

msg.metrics = {
    pack_id: data.pack_id || 'UNKNOWN',
    v_max: v_max,
    v_min: v_min,
    delta_v: parseFloat(delta_v.toFixed(4)),
    delta_v_mv: parseFloat(delta_v_mv.toFixed(1)),
    t_max: t_max,
    timestamp: data.timestamp || new Date().toISOString()
};

// Hierarchy: CRITICAL first, then WARNING, else NORMAL
if (delta_v >= CRIT_THRESHOLD_V || t_max >= MAX_TEMP_CRIT) {
    msg.status = 'CRITICAL';
    msg.reason = `Critical imbalance (${delta_v_mv.toFixed(1)} mV) or extreme temperature (${t_max}°C)`;
    return [null, null, msg, null];
} else if (delta_v >= WARN_THRESHOLD_V || t_max >= MAX_TEMP_WARN) {
    msg.status = 'WARNING';
    msg.reason = `Warning imbalance (${delta_v_mv.toFixed(1)} mV) or elevated temperature (${t_max}°C)`;
    return [null, msg, null, null];
} else {
    msg.status = 'NORMAL';
    msg.reason = 'Nominal operating conditions';
    return [msg, null, null, null];
}

msg.payload = {
    alert_type: msg.status,
    pack_id: msg.metrics ? msg.metrics.pack_id : 'UNKNOWN',
    delta_v_mv: msg.metrics ? msg.metrics.delta_v_mv : null,
    t_max: msg.metrics ? msg.metrics.t_max : null,
    reason: msg.reason,
    timestamp: new Date().toISOString(),
    origin: 'node_red_flow'
};
return msg;
